function monthsToPayoff(balance, apr, payment){
  if(!(balance>0)||!(payment>0)) return null;
  var r=apr/12;
  if(r===0){ if(payment<=0) return null; return Math.ceil(balance/payment); }
  if(payment<=balance*r) return Infinity;
  var bal=balance, m=0;
  while(bal>1e-9 && m<1000000){ var interest=bal*r; var princ=payment-interest; bal-=princ; m++; }
  return m;
}
function schedule(balance, apr, payment){
  if(!(balance>0)||!(payment>0)) return null;
  var r=apr/12, bal=balance, rows=[];
  if(r===0){ var n=Math.ceil(balance/payment); var pp=payment; for(var i=1;i<=n;i++){ var pr=(i===n)?bal:pp; bal-=pr; rows.push({month:i,payment:pp,interest:0,principal:pr,balance:Math.max(0,bal)});} return rows; }
  if(payment<=balance*r) return null;
  var m=0;
  while(bal>1e-9 && m<1000000){ var interest2=bal*r; var princ2=payment-interest2; var ap,apay;
    if(princ2>=bal){ ap=bal; apay=interest2+bal; bal=0; } else { ap=princ2; apay=payment; bal-=princ2; }
    m++; rows.push({month:m,payment:apay,interest:interest2,principal:ap,balance:Math.max(0,bal)});
    if(bal<=1e-9) break; }
  return rows;
}
function totalInterest(balance,apr,payment){var s=schedule(balance,apr,payment);if(!s)return null;var t=0;for(var i=0;i<s.length;i++)t+=s[i].interest;return t;}
